tool_input.command:
cd packages/nodes-base/nodes/KoBoToolbox && python3 - <<'E'
p='KoBoToolbox.node.ts'
s=open(p).read()
s=s.replace("import { NodeConnectionTypes } from 'n8n-workflow';","import { NodeConnectionTypes, NodeOperationError } from 'n8n-workflow';")
s=s.replace("""					const submissionIds = parseSubmissionIds(
						this.getNode(),
						this.getNodeParameter('submissionIds', i) as string,
						i,
					);
					const status = this.getNodeParameter('validationStatus', i) as string;
""","""					const rawSubmissionIds = this.getNodeParameter('submissionIds', i);
					const status = this.getNodeParameter('validationStatus', i);
					if (typeof rawSubmissionIds !== 'string' || typeof status !== 'string') {
						throw new NodeOperationError(
							this.getNode(),
							'Submission IDs and validation status must be strings',
							{ itemIndex: i },
						);
					}
					const submissionIds = parseSubmissionIds(this.getNode(), rawSubmissionIds, i);
""")
open(p,'w').write(s)
E
git diff --stat .
